17	package org.springframework.samples.petclinic.service;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Derives an owner's numeric membership level. The level starts at 1 and gains a
24	 * point for each qualifying attribute:
25	 * <ul>
26	 *   <li>+1 when the owner has an email address on file;</li>
27	 *   <li>+1 when the owner has no namesakes ({@code namesakeCount} is 0).</li>
28	 * </ul>
29	 * The result is capped at {@value #MAX_LEVEL}; level 4 is reserved for tenure.
30	 */
31	@Component
32	public class MembershipLevelEvaluator {
33	
34	    /** The level every owner starts at before any qualifying attribute is counted. */
35	    static final int BASE_LEVEL = 1;
36	
37	    /** Highest level attainable on creation; level 4 is reserved for tenure. */
38	    static final int MAX_LEVEL = 3;
39	
40	    /**
41	     * @param owner the owner whose level is evaluated
42	     * @return the owner's membership level, or {@code null} when the owner is not known
43	     */
44	    public Integer levelFor(Owner owner) {
45	        if (owner == null) {
46	            return null;
47	        }
48	        int level = BASE_LEVEL;
49	        if (owner.hasEmail()) {
50	            level++;
51	        }
52	        if (hasNoNamesakes(owner)) {
53	            level++;
54	        }
55	        return Math.min(level, MAX_LEVEL);
56	    }
57	
58	    private boolean hasNoNamesakes(Owner owner) {
59	        return owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
60	    }
61	}
