217	     */
218	    public Pet getPet(String name) {
219	        return getPet(name, false);
220	    }
221	
222	    /**
223	     * Return the Pet with the given name, or null if none found for this Owner.
224	     *
225	     * @param name to test
226	     * @return true if pet name is already in use
227	     */
228	    public Pet getPet(String name, boolean ignoreNew) {
229	        name = name.toLowerCase();
230	        for (Pet pet : getPetsInternal()) {
231	            if (!ignoreNew || !pet.isNew()) {
232	                String compName = pet.getName();
233	                compName = compName.toLowerCase();
234	                if (compName.equals(name)) {
235	                    return pet;
236	                }
237	            }
238	        }
239	        return null;
240	    }
241	
242	    public Pet getPet(Integer petId) {
243	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
244	    }
