1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.controller.OwnerIdentity;
13	import org.springframework.samples.petclinic.rest.controller.TelephoneFormatter;
14	import org.springframework.samples.petclinic.service.BulkSignupWarningEvaluator;
15	import org.springframework.samples.petclinic.service.MembershipLevelEvaluator;
16	
17	import java.util.Collection;
18	import java.util.List;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public abstract class OwnerMapper {
25	
26	    @Autowired
27	    protected BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
28	
29	    @Autowired
30	    protected MembershipLevelEvaluator membershipLevelEvaluator;
31	
32	    @Autowired
33	    protected OwnerIdentity ownerIdentity;
34	
35	    @Autowired
36	    protected TelephoneFormatter telephoneFormatter;
37	
38	    @Mapping(target = "identityKey", expression = "java(owner == null ? null : ownerIdentity.key(owner))")
39	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
40	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
41	    @Mapping(target = "telephoneDisplay", expression = "java(owner == null ? null : telephoneFormatter.format(owner.getTelephone()))")
42	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
43	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.model.CheckDigit.forOwner(owner))")
44	    @Mapping(target = "membershipLevel", expression = "java(membershipLevelEvaluator.levelFor(owner))")
45	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
46	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarningEvaluator.isWarranted(owner))")
47	    @Mapping(target = "contactPreference", expression = "java(org.springframework.samples.petclinic.model.ContactPreference.forOwner(owner))")
48	    @Mapping(target = "ageBand", expression = "java(org.springframework.samples.petclinic.model.AgeBand.forOwner(owner))")
49	    public abstract OwnerDto toOwnerDto(Owner owner);
50	
51	    /**
52	     * Formats an owner's membership number as {@code "<customerCode>-M<YY>"}, where
53	     * {@code YY} is the last two digits of the registration date's year
54	     * (e.g. {@code "NSW-A1B2C3D4-M26"}). Returns {@code null} until both the customer code
55	     * and registration date have been assigned.
56	     */
57	    protected String formatMembershipNumber(Owner owner) {
58	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
59	            return null;
60	        }
61	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
62	    }
63	
64	    /**
65	     * Derives an owner's locality from its region-and-hash identity: the {@code <REGION>}
66	     * segment of the assigned {@code customerCode}. Owners without a code yet fall back to
67	     * deriving the region straight from their own fields.
68	     */
69	    protected String formatLocality(Owner owner) {
70	        if (owner == null) {
71	            return null;
72	        }
73	        if (owner.getCustomerCode() != null) {
74	            return org.springframework.samples.petclinic.model.Locality.fromCustomerCode(owner.getCustomerCode());
75	        }
76	        return org.springframework.samples.petclinic.model.Locality.forOwner(owner);
77	    }
78	
79	    /**
80	     * Formats an owner's stored names as {@code "LastName, FirstName"} for display.
81	     */
82	    protected String formatDisplayName(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        return owner.getLastName() + ", " + owner.getFirstName();
87	    }
88	
89	    /**
90	     * Builds an owner's initials as the upper-cased first letters of the first and last
91	     * name, dot-separated with a trailing dot (e.g. {@code "J.S."}).
92	     */
93	    protected String formatInitials(Owner owner) {
94	        if (owner == null) {
95	            return null;
96	        }
97	        return initial(owner.getFirstName()) + initial(owner.getLastName());
98	    }
99	
100	    private String initial(String name) {
101	        return Character.toUpperCase(name.charAt(0)) + ".";
102	    }
103	
104	    public abstract Owner toOwner(OwnerDto ownerDto);
105	
106	    @Mapping(target = "id", ignore = true)
107	    @Mapping(target = "pets", ignore = true)
108	    @Mapping(target = "customerCode", ignore = true)
109	    @Mapping(target = "householdId", ignore = true)
110	    @Mapping(target = "namesakeCount", ignore = true)
111	    @Mapping(target = "possibleDuplicate", ignore = true)
112	    @Mapping(target = "possibleDuplicateOf", ignore = true)
113	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
114	
115	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
116	
117	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
118	
119	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
120	        OwnerPageDto ownerPageDto = new OwnerPageDto();
121	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
122	        ownerPageDto.setPage(ownerPage.getNumber());
123	        ownerPageDto.setSize(ownerPage.getSize());
124	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
125	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
126	        return ownerPageDto;
127	    }
128	}
